<?php if(!defined('IN_CRONLITE'))exit;
function ad_risk_check($ui){$ip=$ui['ip']??'';$key='ad_ip_'.$ip;$c=intval(getcache($key));if($c>100)return['is_fraud'=>1,'score'=>100];setcache($key,$c+1,3600);if(empty($ui['ua']??'')||preg_match('/bot|crawler/i',$ui['ua']??''))return['is_fraud'=>1,'score'=>90];return['is_fraud'=>0,'score'=>0];}
function ad_get_best_ad($pos,$ui,$rs){global $DB;$res=$DB->query("SELECT c.*,ag.*,cr.*,a.id as aid FROM ad_campaigns c JOIN ad_groups ag ON c.id=ag.campaign_id JOIN ad_creatives cr ON ag.id=cr.ad_group_id JOIN ad_advertisers a ON c.advertiser_id=a.id WHERE c.status=4 AND ag.status=1 AND cr.status=2 AND c.budget_used<c.budget_total AND c.start_date<=CURDATE() AND c.end_date>=CURDATE()")->fetchAll();if(empty($res))return null;$ads=[];foreach($res as $a){if(!ad_match_targeting($a,$ui))continue;$ecpm=ad_calc_ecpm($a);$ads[]=['creative_id'=>$a['id'],'type'=>$a['type'],'title'=>$a['title'],'description'=>$a['description'],'image_url'=>$a['image_url'],'landing_url'=>$a['landing_url'],'ecpm'=>$ecpm];}if(empty($ads))return null;usort($ads,fn($a,$b)=>$b['ecpm']<=>$a['ecpm']);return $ads[0];}
function ad_match_targeting($a,$ui){if(!empty($a['devices'])){$d=json_decode($a['devices'],1);if(is_array($d)&&!in_array($ui['device']??'unknown',$d))return false;}if(!empty($a['os_list'])){$o=json_decode($a['os_list'],1);if(is_array($o)&&!in_array(strtolower($ui['os']??''),$o))return false;}if(!empty($a['regions'])){$r=json_decode($a['regions'],1);if(is_array($r)&&!in_array($ui['region']??'',$r))return false;}return true;}
function ad_calc_ecpm($a){switch($a['charge_type']){case'CPM':return floatval($a['bid_price']);case'CPC':return floatval($a['bid_price'])*0.01*1000;case'CPA':return floatval($a['bid_price'])*0.01*0.05*1000;case'CPT':return floatval($a['bid_price'])/1000;default:return floatval($a['bid_price']);}}
function ad_log_risk($rid,$ui,$r){global $DB;$DB->query("INSERT INTO ad_risk_logs(request_id,user_id,ip,risk_score,is_fraud,fraud_type,event_type)VALUES('$rid','".($ui['user_id']??'')."','".($ui['ip']??'')."','".$r['score']."','".$r['is_fraud']."','".$r['type']."','impression')");}
?>
